import { generateReport } from '/private/tmp/100-tricks-runs/d61/without/h2-eval-thresholds/r9/packages/frai-core/src/eval/index.js';

// Test 1: Report without thresholds
const evaluations = [
  { id: 'exact_match', label: 'Exact Match', score: 0.75, total: 4 },
  { id: 'toxicity', label: 'Toxicity', score: 0.9, total: 4 },
  { id: 'length_variance', label: 'Length Variance', score: 0.85, total: 4 }
];

const reportNoThresholds = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json'
});

console.log('Test 1: Report without thresholds');
console.log('Has passed field:', 'passed' in reportNoThresholds);
console.log('Has thresholds field:', 'thresholds' in reportNoThresholds);
console.log('✓ Test 1 passed\n');

// Test 2: Report with passing thresholds
const reportPass = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.5, toxicity: 0.8 }
});

console.log('Test 2: Report with passing thresholds');
console.log('passed:', reportPass.passed);
console.log('thresholds count:', reportPass.thresholds.length);
console.log('All passed:', reportPass.thresholds.every(t => t.passed === true));
console.log('✓ Test 2 passed\n');

// Test 3: Report with failing thresholds
const reportFail = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: { exact_match: 0.9 }
});

console.log('Test 3: Report with failing thresholds');
console.log('passed:', reportFail.passed);
console.log('threshold passed:', reportFail.thresholds[0].passed);
console.log('✓ Test 3 passed\n');

// Test 4: Report with metric with no score (null)
const evaluationsWithNull = [
  { id: 'exact_match', label: 'Exact Match', score: null, total: 0 },
  { id: 'toxicity', label: 'Toxicity', score: 1, total: 4 }
];

const reportNull = generateReport({
  evaluations: evaluationsWithNull,
  outputsPath: '/tmp/outputs.json',
  referencesPath: null,
  thresholds: { exact_match: 0.5 }
});

console.log('Test 4: Metric with null score fails threshold');
console.log('passed:', reportNull.passed);
console.log('threshold.score:', reportNull.thresholds[0].score);
console.log('threshold.passed:', reportNull.thresholds[0].passed);
console.log('✓ Test 4 passed\n');

console.log('✓ All tests passed!');
EOF
